/**
 * Expo config plugin: sign the Android release build with a real keystore.
 *
 * Why this exists: `expo prebuild` generates `android/app/build.gradle` with
 * `release { signingConfig signingConfigs.debug }`. A debug-signed "release"
 * APK installs and runs fine, but it can never be replaced by a genuinely
 * signed build — Android rejects the update as a signature mismatch. For an app
 * people install by downloading a file, that is a dead end.
 *
 * `android/` is regenerated by prebuild, so the signing config cannot live in
 * a checked-in Gradle file — it has to be injected at prebuild time. That is
 * what this plugin does (AGENTS.md: never hand-edit `android/`).
 *
 * Inputs (environment variables, normally fed from GitHub Actions secrets):
 *   THMMY_KEYSTORE_FILE       path to the .keystore, relative to android/app
 *   THMMY_KEYSTORE_PASSWORD   keystore password
 *   THMMY_KEY_ALIAS           key alias
 *   THMMY_KEY_PASSWORD        key password
 *
 * When those are absent — a local build, or a fork without secrets — the plugin
 * is a no-op and Gradle keeps its debug signing. CI prints a warning so an
 * unsigned release is never mistaken for a signed one.
 */
const { withAppBuildGradle } = require('@expo/config-plugins');

const ENV = {
  file: 'THMMY_KEYSTORE_FILE',
  storePassword: 'THMMY_KEYSTORE_PASSWORD',
  keyAlias: 'THMMY_KEY_ALIAS',
  keyPassword: 'THMMY_KEY_PASSWORD',
};

/** Gradle single-quoted string escaping (only \\ and ' are special). */
function gq(value) {
  return "'" + String(value).replace(/\\/g, '\\\\').replace(/'/g, "\\'") + "'";
}

/**
 * Add a `release` signingConfig to the signingConfigs block.
 *
 * Anchored on `signingConfigs {` and closed by brace counting rather than a
 * fixed offset, so it survives prebuild changing its indentation or adding
 * entries.
 */
function insertSigningConfig(contents) {
  const anchor = contents.indexOf('signingConfigs {');
  if (anchor === -1) {
    throw new Error(
      'withAndroidReleaseSigning: no signingConfigs block in app/build.gradle. ' +
        'Expo prebuild output changed; update this plugin.',
    );
  }

  // Walk forward counting braces to find where the block actually closes.
  const open = contents.indexOf('{', anchor);
  let depth = 0;
  let close = -1;
  for (let i = open; i < contents.length; i++) {
    const ch = contents[i];
    if (ch === '{') depth++;
    else if (ch === '}') {
      depth--;
      if (depth === 0) {
        close = i;
        break;
      }
    }
  }
  if (close === -1) {
    throw new Error('withAndroidReleaseSigning: unterminated signingConfigs block.');
  }

  const block =
    '\n        release {\n' +
    '            storeFile file(' + gq(process.env[ENV.file]) + ')\n' +
    '            storePassword ' + gq(process.env[ENV.storePassword]) + '\n' +
    '            keyAlias ' + gq(process.env[ENV.keyAlias]) + '\n' +
    '            keyPassword ' + gq(process.env[ENV.keyPassword]) + '\n' +
    '        }\n    ';

  return contents.slice(0, close) + block + contents.slice(close);
}

/**
 * Point the `release` buildType at signingConfigs.release.
 *
 * `signingConfig signingConfigs.debug` appears in both the debug and release
 * buildTypes, so this searches forward from `buildTypes {` for the `release {`
 * entry and only replaces the first match after it.
 */
function repointReleaseBuildType(contents) {
  const buildTypes = contents.indexOf('buildTypes {');
  if (buildTypes === -1) {
    throw new Error(
      'withAndroidReleaseSigning: no buildTypes block in app/build.gradle.',
    );
  }

  const releaseAt = contents.indexOf('release {', buildTypes);
  if (releaseAt === -1) {
    throw new Error(
      'withAndroidReleaseSigning: no release buildType in app/build.gradle.',
    );
  }

  const signingAt = contents.indexOf('signingConfig signingConfigs.debug', releaseAt);
  if (signingAt === -1) {
    throw new Error(
      'withAndroidReleaseSigning: release buildType has no debug signingConfig to replace.',
    );
  }

  return (
    contents.slice(0, signingAt) +
    'signingConfig signingConfigs.release' +
    contents.slice(signingAt + 'signingConfig signingConfigs.debug'.length)
  );
}

module.exports = function withAndroidReleaseSigning(config) {
  const values = Object.values(ENV).map((k) => process.env[k]);
  if (values.some((v) => !v)) {
    console.warn(
      '[withAndroidReleaseSigning] No keystore env vars set — release build will be ' +
        'DEBUG-SIGNED. Set THMMY_KEYSTORE_FILE, THMMY_KEYSTORE_PASSWORD, ' +
        'THMMY_KEY_ALIAS, THMMY_KEY_PASSWORD to produce a properly signed APK.',
    );
    return config;
  }

  return withAppBuildGradle(config, (cfg) => {
    if (cfg.modResults.language !== 'groovy') {
      throw new Error(
        'withAndroidReleaseSigning: expected a Groovy app/build.gradle, got ' +
          cfg.modResults.language,
      );
    }
    cfg.modResults.contents = repointReleaseBuildType(
      insertSigningConfig(cfg.modResults.contents),
    );
    return cfg;
  });
};
